const realMadridElite: EliteExerciseData[] = [
  { title: "La Fábrica: Primer toque orientado bajo presión", description: "El jugador recibe un pase desde distintos ángulos mientras un defensor se acerca a presionar. Debe controlar con un solo toque orientando el balón hacia el espacio libre. Se realizan series de 8 repeticiones por lado, alternando pie derecho e izquierdo. El entrenador varía la velocidad del pase y la dirección de la presión. El objetivo es desarrollar la capacidad de leer el entorno antes de recibir.", category: "ball_control", minAge: 10, maxAge: 16, difficulty: "intermediate", durationMinutes: 15, playersRequired: 3, materials: "Balones, conos, petos", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Conducción a velocidad con cambio de ritmo", description: "Circuito de 40 metros con zonas marcadas donde el jugador debe acelerar y desacelerar con el balón pegado al pie. Se colocan conos cada 5 metros alternando zonas de sprint y zonas de pausa controlada. El jugador debe mantener la cabeza levantada y usar ambos pies. Se cronometra cada pasada y se busca mejorar el tiempo sin perder el control. Ideal para desarrollar la conducción a alta velocidad.", category: "ball_control", minAge: 10, maxAge: 18, difficulty: "intermediate", durationMinutes: 12, playersRequired: 1, materials: "Balón, conos, cronómetro", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Definición con ambos perfiles", description: "Desde el borde del área, el jugador recibe pases alternados por derecha e izquierda y debe definir con el pie correspondiente al lado del pase. Se trabajan series de 10 remates por perfil con énfasis en la colocación sobre la potencia. El portero participa activamente y se analizan los ángulos de tiro. Se incluye variante con defensor pasivo. El objetivo es eliminar la dependencia del pie dominante en la finalización.", category: "shooting", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 20, playersRequired: 4, materials: "Balones, arco, conos", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Tiro de media distancia con preparación", description: "El mediocampista recibe un pase de espaldas al arco, gira y ejecuta un disparo desde 20-25 metros. Se practican tres variantes: control y tiro, tiro de primera, y tiro tras amague. Cada jugador realiza 12 repeticiones totales. Se enfatiza la posición del cuerpo sobre el balón y el seguimiento del disparo. El portero trabaja simultáneamente su posicionamiento ante tiros lejanos.", category: "shooting", minAge: 14, maxAge: 18, difficulty: "advanced", durationMinutes: 20, playersRequired: 4, materials: "Balones, arco, conos", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Rondo técnico 4v2 con transición", description: "Cuatro atacantes mantienen posesión contra dos defensores en un espacio de 8x8 metros. Al recuperar el balón, los defensores deben completar 3 pases entre ellos para ganar un punto. Los atacantes que pierden el balón pasan a defender inmediatamente. Se juegan rondas de 3 minutos con rotación. El enfoque está en la calidad del primer toque y la velocidad de decisión.", category: "passing", minAge: 10, maxAge: 16, difficulty: "intermediate", durationMinutes: 15, playersRequired: 6, materials: "Balón, conos, petos", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Control aéreo y volea", description: "Un servidor lanza balones aéreos desde 15 metros y el jugador debe controlar con pecho o muslo y rematar de volea antes del segundo bote. Se alternan lanzamientos altos, medios y con efecto. Cada jugador realiza 10 repeticiones y se evalúa la limpieza del control y la precisión del remate. Se incluye variante con defensor que disputa el balón aéreo. Ejercicio clave para delanteros y mediocampistas ofensivos.", category: "shooting", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 18, playersRequired: 3, materials: "Balones, arco", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Pase al tercer hombre", description: "Tres jugadores se posicionan en triángulo con un defensor en el centro. El balón debe llegar al tercer hombre mediante combinación rápida de pases. Se trabaja el timing del desmarque y la comunicación visual entre los atacantes. Cada secuencia debe completarse en máximo 4 toques totales. Se realizan 15 repeticiones rotando posiciones. Fundamental para el juego combinativo del Real Madrid.", category: "passing", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 15, playersRequired: 4, materials: "Balón, conos, petos", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Recepción en giro con oposición", description: "El mediocampista recibe de espaldas al arco con un defensor pegado. Debe usar el cuerpo para proteger, ejecutar un giro y salir conduciendo hacia adelante. Se practican giros por ambos lados con variantes: Cruyff turn, giro con planta, media vuelta. Series de 8 repeticiones por lado. El defensor aumenta la intensidad progresivamente. Ejercicio esencial para mediocampistas creativos.", category: "ball_control", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 15, playersRequired: 3, materials: "Balones, conos", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Circuito de finalización rápida", description: "Cuatro estaciones de remate con diferentes situaciones: tiro tras pared, cabezazo tras centro, definición 1v1, y remate de segunda jugada. Los jugadores rotan cada 3 minutos completando el circuito dos veces. Se enfatiza la velocidad de ejecución y la toma de decisiones bajo presión. El portero rota entre estaciones. Se registran los goles por estación para fomentar la competitividad.", category: "shooting", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 25, playersRequired: 8, materials: "Balones, arco, conos, petos", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Posesión con objetivo de profundidad", description: "Dos equipos de 5 jugadores disputan posesión en campo de 30x20 metros con dos mini arcos en cada extremo. El equipo en posesión debe completar 5 pases antes de poder atacar los mini arcos. Se trabaja la paciencia en la construcción y la verticalidad cuando aparece el espacio. Periodos de 4 minutos con descanso activo. Se cuentan los goles y las secuencias de 5+ pases.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 20, playersRequired: 10, materials: "Balón, conos, petos, mini arcos", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: true, gameFormat: "5v5" },
  { title: "La Fábrica: Pase largo con precisión milimétrica", description: "Parejas separadas a 35 metros practican pases largos que deben caer dentro de un cuadrado de 3x3 metros marcado con conos. Se alternan pases rasos, a media altura y aéreos con efecto. Cada jugador ejecuta 15 pases y se contabilizan los que caen en la zona objetivo. Se incluye variante con receptor en movimiento. Ejercicio fundamental para centrales y mediocampistas que cambian el juego.", category: "passing", minAge: 14, maxAge: 18, difficulty: "advanced", durationMinutes: 15, playersRequired: 2, materials: "Balones, conos", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Duelo 1v1 ofensivo en banda", description: "El extremo recibe el balón en la banda y debe superar al lateral en un espacio de 15x10 metros para enviar un centro al área. Se practican regates específicos: recorte interior, bicicleta, cambio de ritmo, y autopase. Cada jugador ataca 8 veces por cada lado. Se evalúa el éxito del regate y la calidad del centro posterior. Ejercicio diseñado para extremos y laterales ofensivos.", category: "individual", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 18, playersRequired: 4, materials: "Balones, conos, arco", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Juego de posición 3-2 con comodín", description: "Tres atacantes y un comodín intentan mantener posesión contra dos defensores en espacio de 12x12 metros. El comodín siempre juega con el equipo en posesión y debe ubicarse en el espacio más ventajoso. Se limita a 2 toques para atacantes y libre para el comodín. Rondas de 2 minutos con rotación de defensores. Se enfatiza el movimiento sin balón y la creación de líneas de pase.", category: "tactics", minAge: 10, maxAge: 16, difficulty: "intermediate", durationMinutes: 15, playersRequired: 6, materials: "Balón, conos, petos", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Tiro de primera tras pase filtrado", description: "El mediocampista envía un pase filtrado entre dos conos que simulan defensores y el delantero debe rematar de primera sin parar el balón. Se varía la dirección del pase: diagonal, frontal y desde banda. Cada delantero ejecuta 12 remates y se registra la efectividad. El portero trabaja reflejos y posicionamiento. Se añade presión temporal con un defensor que persigue desde atrás.", category: "shooting", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 15, playersRequired: 4, materials: "Balones, arco, conos", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Control de pases tensos a ras de suelo", description: "En parejas a 12 metros de distancia, un jugador envía pases tensos a ras de suelo y el receptor debe amortiguar con interior del pie y devolver en un solo movimiento fluido. Se realizan series de 20 pases por pie, aumentando progresivamente la velocidad del pase. Se evalúa que el balón no se despegue más de 30 cm del pie en la recepción. Variante avanzada: recepción con exterior del pie.", category: "ball_control", minAge: 10, maxAge: 16, difficulty: "intermediate", durationMinutes: 12, playersRequired: 2, materials: "Balones", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Partido 4v4 con porterías pequeñas", description: "Partido en espacio reducido de 25x18 metros con porterías de 2 metros sin portero. Máximo 3 toques por jugador. Se enfatiza el juego rápido, la movilidad constante y la finalización precisa. Periodos de 5 minutos con 1 minuto de descanso. Se juegan 4 periodos y se lleva marcador acumulado. Regla especial: gol de primera vale doble. Ideal para desarrollar la toma de decisiones rápida.", category: "tactics", minAge: 10, maxAge: 16, difficulty: "intermediate", durationMinutes: 25, playersRequired: 8, materials: "Balón, conos, mini arcos", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: true, gameFormat: "4v4" },
  { title: "La Fábrica: Ejercicio de visión periférica", description: "El jugador conduce el balón en un espacio de 20x20 metros mientras el entrenador levanta conos de colores en diferentes posiciones. El jugador debe gritar el color sin dejar de conducir. Se realizan series de 90 segundos con descanso de 30 segundos. Progresión: añadir un defensor pasivo que el jugador debe esquivar. Desarrolla la capacidad de mantener la cabeza levantada mientras se controla el balón.", category: "individual", minAge: 8, maxAge: 14, difficulty: "beginner", durationMinutes: 12, playersRequired: 2, materials: "Balón, conos de colores", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Combinación ofensiva en zona 14", description: "Tres atacantes y un mediocampista practican combinaciones prediseñadas en la zona 14 (frente al área). Se ensayan 4 movimientos: pared y diagonal, overlap con centro, pase al espacio y desmarque de ruptura. Cada combinación se repite 6 veces antes de pasar a la siguiente. Se añade oposición progresiva: primero sin defensores, luego con 2, finalmente con 4. Culmina siempre en finalización.", category: "tactics", minAge: 14, maxAge: 18, difficulty: "advanced", durationMinutes: 25, playersRequired: 8, materials: "Balones, arco, conos, petos", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Dominio de balón con ambos pies cronometrado", description: "El jugador debe completar una secuencia de 50 toques alternando pies sin que el balón toque el suelo. Se cronometra el tiempo y se registra el récord personal. Progresión: añadir muslo, cabeza y hombro a la secuencia. Se realizan 5 intentos por sesión. Los jugadores compiten entre sí por el mejor tiempo con la secuencia completa. Ejercicio fundamental para el desarrollo técnico individual en La Fábrica.", category: "ball_control", minAge: 8, maxAge: 14, difficulty: "beginner", durationMinutes: 10, playersRequired: 1, materials: "Balón, cronómetro", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Centro y remate en movimiento continuo", description: "Dos extremos alternan centros desde ambas bandas mientras tres delanteros atacan el área en rotación continua. Cada delantero debe rematar y salir inmediatamente para dar espacio al siguiente. Se realizan 3 rondas de 3 minutos. Se trabajan centros rasos, a media altura y al segundo palo. Se contabilizan goles y se premia la variedad en el tipo de remate. Ejercicio de alta intensidad para el ataque.", category: "shooting", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 20, playersRequired: 7, materials: "Balones, arco, conos", methodologySource: "Real Madrid (La Fábrica)", isSmallSidedGame: false, gameFormat: null },
];

