// ==================== COMBINE ALL ELITE EXERCISES ====================
const allEliteExercises: EliteExerciseData[] = [
  ...realMadridElite,
  ...bayernMunichElite,
  ...manchesterCityElite,
  ...liverpoolElite,
  ...juventusElite,
  ...psgElite,
  ...dortmundElite,
  ...benficaElite,
  ...santosFCElite,
  ...clubAmericaElite,
];

export async function seedEliteExercises() {
  const existingCount = await prisma.exercise.count();
  if (existingCount > 200) {
    console.log(`Exercises already seeded (${existingCount} found, >200). Skipping elite exercises.`);
    return;
  }

  console.log(`Seeding ${allEliteExercises.length} elite exercises...`);

  await prisma.exercise.createMany({
    data: allEliteExercises.map((e) => ({
      title: e.title,
      description: e.description,
      category: e.category,
      minAge: e.minAge,
      maxAge: e.maxAge,
      difficulty: e.difficulty,
      durationMinutes: e.durationMinutes,
      playersRequired: e.playersRequired,
      materials: e.materials,
      methodologySource: e.methodologySource,
      isSmallSidedGame: e.isSmallSidedGame,
      gameFormat: e.gameFormat,
      isExternal: false,
    })),
  });

  console.log(`✅ ${allEliteExercises.length} elite exercises seeded successfully.`);
}

// Allow running standalone
if (require.main === module) {
  seedEliteExercises()
    .catch((e) => {
      console.error(e);
      process.exit(1);
    })
    .finally(async () => {
      await prisma.$disconnect();
    });
}
